import React, { useState } from 'react';
import './CSS/AdminDashboard.css';

const AdminDashboard = () => {
  const [logs] = useState([
    { id: 1, user: "Anisha (Seller)", role: "Seller", action: "Added product 'Wireless Earbuds'", timestamp: "2026-09-07 10:15 AM" },
    { id: 2, user: "Mona (User)", role: "User", action: "Placed order #1042 for $149", timestamp: "2026-09-07 10:22 AM" },
    { id: 3, user: "Bharath (Seller)", role: "Seller", action: "Updated price of 'Flagship Smartphone'", timestamp: "2026-09-07 10:30 AM" },
    { id: 4, user: "Bharath (User)", role: "User", action: "Added 'Gaming Laptop' to cart", timestamp: "2026-09-07 10:40 AM" }
  ]);
  const [accounts, setAccounts] = useState([
    { id: 101, name: "Anisha", email: "anisha@seller.com", role: "Seller", status: "Active" },
    { id: 102, name: "Mona", email: "mona@gmail.com", role: "User", status: "Active" },
    { id: 103, name: "Jhanvi", email: "jhanvi@gmail.com", role: "User", status: "Active" },
    { id: 104, name: "Bharath", email: "bharath@seller.com", role: "Seller", status: "Blocked" }
  ]);

  const toggleStatus = (id) => {
    setAccounts(prev =>
      prev.map(acc => {
        if (acc.id === id) {
          const newStatus = acc.status === "Active" ? "Blocked" : "Active";
          return { ...acc, status: newStatus };
        }
        return acc;
      })
    );
  };

  return (
    <div className="admin-container">
      <div className="admin-header">
        <h2>Admin Management Dashboard</h2>
        <p>Monitor platform operations and control account access permissions</p>
      </div>

      {/* Account Access Control Table */}
      <div className="admin-card">
        <h3>User & Seller Access Management</h3>
        <table className="admin-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Name</th>
              <th>Email</th>
              <th>Role</th>
              <th>Status</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {accounts.map(acc => (
              <tr key={acc.id}>
                <td>#{acc.id}</td>
                <td>{acc.name}</td>
                <td>{acc.email}</td>
                <td>
                  <span className={`role-badge ${acc.role.toLowerCase()}`}>{acc.role}</span>
                </td>
                <td>
                  <span className={`status-badge ${acc.status.toLowerCase()}`}>{acc.status}</span>
                </td>
                <td>
                  <button
                    className={`action-btn ${acc.status === "Active" ? "btn-block" : "btn-grant"}`}
                    onClick={() => toggleStatus(acc.id)}
                  >
                    {acc.status === "Active" ? "Block Access" : "Grant Access"}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Action Audit Logs */}
      <div className="admin-card">
        <h3>Activity Audit Logs</h3>
        <table className="admin-table">
          <thead>
            <tr>
              <th>Timestamp</th>
              <th>Actor</th>
              <th>Role</th>
              <th>Performed Action</th>
            </tr>
          </thead>
          <tbody>
            {logs.map(log => (
              <tr key={log.id}>
                <td className="log-time">{log.timestamp}</td>
                <td>{log.user}</td>
                <td>
                  <span className={`role-badge ${log.role.toLowerCase()}`}>{log.role}</span>
                </td>
                <td>{log.action}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default AdminDashboard;
